export const LINES=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
export const FEATURES=['Claim small board','Block local win','Create local fork','Local threats','Opponent threats','Cell centre','Cell corner','Win whole game','Stop macro threat','Board centre','Board corner','Give free choice','Send to opponent threat','Send to own threat','Send to macro danger','Return to same board','Own open lines','Opponent open lines'];
export function rng(seed=42){return ()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return ((t^t>>>14)>>>0)/4294967296;};}
export function fresh(){return {cells:Array(81).fill(0),boards:Array(9).fill(0),next:-1,turn:1,winner:0,ply:0,last:-1};}
export function win(a){for(const [x,y,z] of LINES)if((a[x]===1||a[x]===-1)&&a[x]===a[y]&&a[x]===a[z])return a[x];return 0;}
export function legal(s){if(s.winner)return [];const out=[];for(let b=0;b<9;b++)if(!s.boards[b]&&(s.next===-1||s.next===b))for(let c=0;c<9;c++)if(!s.cells[b*9+c])out.push(b*9+c);return out;}
export function play(s,a){if(!Number.isInteger(a)||!legal(s).includes(a))throw Error('Illegal move');const n={...s,cells:s.cells.slice(),boards:s.boards.slice()},b=Math.floor(a/9),c=a%9;n.cells[a]=s.turn;const mini=n.cells.slice(b*9,b*9+9);n.boards[b]=win(mini)||(mini.every(Boolean)?2:0);n.winner=win(n.boards)||(n.boards.every(Boolean)?2:0);n.next=n.boards[c]?-1:c;n.turn=-s.turn;n.ply++;n.last=a;return n;}
function threats(a,p){
  // A completed board is closed: empty cells cannot be future winning moves.
  if(win(a)||a.every(Boolean))return 0;
  let n=0;for(let i=0;i<9;i++)if(!a[i]){a[i]=p;if(win(a)===p)n++;a[i]=0;}return n;
}
function open(a,p){return LINES.filter(l=>l.every(i=>a[i]===0||a[i]===p)).length/8;}
export function features(s,a){const p=s.turn,b=Math.floor(a/9),c=a%9,mini=s.cells.slice(b*9,b*9+9),macro=s.boards.slice();mini[c]=-p;const block=win(mini)===-p;mini[c]=p;const capture=win(mini)===p;const ownT=threats(mini,p),oppT=threats(mini,-p);macro[b]=-p;const macroBlock=capture&&win(macro)===-p;macro[b]=capture?p:(mini.every(Boolean)?2:0);const macroWin=win(macro)===p,free=!!macro[c];const dest=c===b?mini:s.cells.slice(c*9,c*9+9);const dt=free?0:threats(dest,-p),ot=free?0:threats(dest,p);const m=macro.slice();m[c]=-p;const danger=!free&&dt>0&&win(m)===-p;return [capture?1:0,block?1:0,ownT>=2?1:0,ownT/4,oppT/4,c===4?1:0,[0,2,6,8].includes(c)?1:0,macroWin?1:0,macroBlock?1:0,b===4?1:0,[0,2,6,8].includes(b)?1:0,free?1:0,dt/4,ot/4,danger?1:0,b===c?1:0,open(mini,p),open(mini,-p)];}
export function policy(s,w,epsilon=0){const actions=legal(s),fs=actions.map(a=>features(s,a)),logits=fs.map(f=>f.reduce((v,x,i)=>v+x*w[i],0)),max=Math.max(...logits),ex=logits.map(x=>Math.exp(x-max)),sum=ex.reduce((a,b)=>a+b,0),soft=ex.map(x=>x/sum),probs=soft.map(x=>(1-epsilon)*x+epsilon/actions.length);return {actions,fs,soft,probs};}
export function choose(s,w,epsilon=0,random=Math.random,gradient=false){const d=policy(s,w,epsilon);let i=0,v=random();for(;i<d.probs.length-1;i++){v-=d.probs[i];if(v<=0)break;}let grad=null;if(gradient){const ratio=(1-epsilon)*d.soft[i]/d.probs[i];grad=d.fs[i].map((x,j)=>ratio*(x-d.fs.reduce((sum,f,k)=>sum+d.soft[k]*f[j],0)));}return {action:d.actions[i],prob:d.probs[i],grad};}
export function makeAgent(){return {weights:Array(FEATURES.length).fill(0),baseline:0,updates:0};}
export function learn(agent,steps,lr=.035,gamma=.99){let ret=0,avg=0;const delta=Array(FEATURES.length).fill(0);for(let k=steps.length-1;k>=0;k--){ret=steps[k].reward+gamma*ret;avg+=ret;const adv=ret-agent.baseline;steps[k].grad.forEach((g,j)=>delta[j]+=adv*g);}const norm=Math.max(1,Math.sqrt(delta.reduce((v,x)=>v+x*x,0))/5);for(let j=0;j<delta.length;j++)agent.weights[j]=Math.max(-12,Math.min(12,agent.weights[j]+lr*delta[j]/norm));agent.baseline=.98*agent.baseline+.02*avg/Math.max(1,steps.length);agent.updates++;}
export function startEpisode(episode){return {state:fresh(),traces:[[],[]],aMark:episode%2===0?1:-1,events:[],result:0};}
export function advance(ep,agents,epsilon,random=Math.random){const s=ep.state,id=s.turn===ep.aMark?0:1;const picked=choose(s,agents[id].weights,epsilon,random,true),n=play(s,picked.action),b=Math.floor(picked.action/9),capture=!s.boards[b]&&n.boards[b]===s.turn;ep.traces[id].push({grad:picked.grad,reward:capture?.12:0});if(capture&&ep.traces[1-id].length)ep.traces[1-id].at(-1).reward-=.12;if(n.winner){ep.result=n.winner===2?2:(n.winner===ep.aMark?0:1);for(let i=0;i<2;i++)if(ep.traces[i].length)ep.traces[i].at(-1).reward+=n.winner===2?0:(ep.result===i?1:-1);}ep.state=n;return {action:picked.action,id,prob:picked.prob,capture};}
export function finish(ep,agents,lr){for(let i=0;i<2;i++)learn(agents[i],ep.traces[i],lr);}
export function episode(agents,index,epsilon,random,lr=.035){const ep=startEpisode(index);while(!ep.state.winner)advance(ep,agents,epsilon,random);finish(ep,agents,lr);return ep;}
export function evaluate(agents,games=40,seed=9000,tactical=false){return agents.map(agent=>{let wins=0,draws=0;const random=rng(seed);for(let k=0;k<games;k++){let s=fresh(),mark=k%2===0?1:-1;while(!s.winner){let a;if(s.turn===mark)a=choose(s,agent.weights,0,random).action;else{const moves=legal(s);if(tactical){let best=-Infinity,candidates=[];for(const m of moves){const f=features(s,m),score=100*f[7]+12*f[0]+8*f[8]+5*f[1]+2*f[2]-8*f[14]-2*f[12]-.7*f[11];if(score>best){best=score;candidates=[m];}else if(score===best)candidates.push(m);}a=candidates[Math.floor(random()*candidates.length)];}else a=moves[Math.floor(random()*moves.length)];}s=play(s,a);}if(s.winner===mark)wins++;else if(s.winner===2)draws++;}return {wins,draws,losses:games-wins-draws,games,score:(wins+.5*draws)/games};});}
